// Generates assets/js/i18n/<locale>.js from _data/i18n.json (the editable source).
// Run `node scripts/build-i18n.cjs`; `--check` fails if generated files are stale.
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const outDir = path.join(root, 'assets/js/i18n');

function build() {
  const { locales, rows } = JSON.parse(fs.readFileSync(path.join(root, '_data/i18n.json'), 'utf8'));
  return locales.map((locale, index) => {
    const entries = Object.entries(rows).map(([key, values]) => {
      if (values.length !== locales.length) throw new Error(`i18n row "${key}" needs ${locales.length} values`);
      return `  ${JSON.stringify(key)}: ${JSON.stringify(values[index])}`;
    });
    return [locale, `// Generated by scripts/build-i18n.cjs from _data/i18n.json. Do not edit.\ni18n[${JSON.stringify(locale)}] = {\n${entries.join(',\n')}\n};\n`];
  });
}

const check = process.argv.includes('--check');
let stale = false;
fs.mkdirSync(outDir, { recursive: true });
for (const [locale, content] of build()) {
  const file = path.join(outDir, `${locale}.js`);
  if (check) {
    if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content) { console.error(`stale: ${file}`); stale = true; }
  } else fs.writeFileSync(file, content);
}
process.exit(stale ? 1 : 0);
